//! MQTT payload -> VssSample mapping (mapping.rs), no broker or transport.
//!
//! Each test feeds raw MQTT payload bytes (`br#"..."#` is a byte string
//! literal, so the JSON needs no escaping) and checks the resulting sample.

use vss_publisher::config::MappingConfig;
use vss_publisher::mapping::{Mapper, MappingError};

const VSS_PATH: &str = "Vehicle.Powertrain.TractionBattery.Temperature.Max";

/// A real message from the AZ3166 firmware.
const BOARD_MESSAGE: &[u8] = br#"{"pressure_hPa":1215.87,"temperature_degC":24.65,"humidity_perc":54.11,"acceleration_mg":[-38.43,13.85,1011.26],"magnetic_mG":[-91.50,-99.00,-384.00],"counter":31}"#;

fn mapper() -> Mapper {
    Mapper::new(MappingConfig::default(), None)
}

/// Minimal board-style message with only the two keys we use.
fn msg(counter: &str, temperature: &str) -> Vec<u8> {
    format!(r#"{{"temperature_degC": {temperature}, "counter": {counter}}}"#).into_bytes()
}

// The real board message: temperature and counter mapped, the other sensor
// values ignored, first seq = 1.
#[test]
fn maps_real_board_message() {
    let s = mapper().map(BOARD_MESSAGE).unwrap();
    assert_eq!(s.path, VSS_PATH);
    assert_eq!(s.value, 24.65);
    assert_eq!(s.rolling_counter, Some(31));
    assert_eq!(s.seq, 1);
}

// Key names come from the config, so a firmware rename needs no code change.
#[test]
fn key_names_are_configurable() {
    let cfg = MappingConfig {
        temperature_field: "temp".into(),
        counter_field: "alive".into(),
        ..MappingConfig::default()
    };
    let s = Mapper::new(cfg, None)
        .map(br#"{"temp": 30.5, "alive": 7}"#)
        .unwrap();
    assert_eq!((s.value, s.rolling_counter), (30.5, Some(7)));
}

// Numbers sent as strings (common in embedded JSON) are accepted.
#[test]
fn numeric_strings_are_accepted() {
    let s = mapper().map(&msg("\"12\"", "\"38.25\"")).unwrap();
    assert_eq!(s.value, 38.25);
    assert_eq!(s.rolling_counter, Some(12));
}

// Every way a payload can be unusable gives a specific error naming the key.
#[test]
fn missing_or_invalid_fields_are_errors() {
    let mut m = mapper();
    assert_eq!(
        m.map(br#"{"counter": 1}"#),
        Err(MappingError::MissingField("temperature_degC".into()))
    );
    assert_eq!(
        m.map(br#"{"temperature_degC": 41.5}"#),
        Err(MappingError::MissingField("counter".into()))
    );
    // The old key names are not accepted any more.
    assert_eq!(
        m.map(br#"{"rollingCounter": 1, "temperature": 41.5}"#),
        Err(MappingError::MissingField("temperature_degC".into()))
    );
    assert!(matches!(
        m.map(&msg("1", "\"hot\"")),
        Err(MappingError::NotANumber(k, _)) if k == "temperature_degC"
    ));
    assert!(matches!(
        m.map(&msg("1", "\"NaN\"")),
        Err(MappingError::NotANumber(..))
    ));
    // Counter must be a non-negative integer.
    for counter in ["-1", "1.5", "\"x\""] {
        assert!(
            matches!(
                m.map(&msg(counter, "41.5")),
                Err(MappingError::NotACounter(k, _)) if k == "counter"
            ),
            "{counter}"
        );
    }
    // JSON null counts as "missing".
    assert_eq!(
        m.map(&msg("null", "41.5")),
        Err(MappingError::MissingField("counter".into()))
    );
    // Valid JSON, but not an object.
    assert!(matches!(m.map(b"41.5"), Err(MappingError::InvalidJson(_))));
}

// 500 C is nonsense, but filtering it here would hide it from the Guardian.
#[test]
fn implausible_temperature_is_forwarded_for_the_guardian_to_judge() {
    let s = mapper().map(&msg("1", "500")).unwrap();
    assert_eq!(s.value, 500.0);
}

// seq advances whenever the counter changes (also 255 -> 0) and stays the
// same when the counter repeats, so the Guardian can see duplicates.
#[test]
fn sequence_follows_counter_changes_and_repeats_for_same_counter() {
    let mut m = mapper();
    let readings = [
        ("254", "41.5"),
        ("254", "41.5"), // re-delivery
        ("255", "41.5"),
        ("0", "41.6"), // wrap-around
        ("0", "41.7"), // frozen counter
    ];
    let seqs: Vec<u64> = readings
        .iter()
        .map(|(c, t)| m.map(&msg(c, t)).unwrap().seq)
        .collect();
    assert_eq!(seqs, vec![1, 1, 2, 3, 3]);
}

// Pins the exact JSON the Guardian expects (its VssSample in contract.rs).
// If this test has to change, the Guardian has to change too.
#[test]
fn output_matches_guardian_input_contract() {
    let mut m = Mapper::new(MappingConfig::default(), Some("run-7".into()));
    let s = m.map(BOARD_MESSAGE).unwrap();
    let json: serde_json::Value = serde_json::to_value(&s).unwrap();
    assert_eq!(
        json,
        serde_json::json!({
            "path": VSS_PATH,
            "value": 24.65,
            "seq": 1,
            "rolling_counter": 31,
            "correlation_id": "run-7",
        })
    );
}
